translations.zh.modalPlan='项目的买入手续费（2%）和卖出手续费（2%）将用于支持 SAFU，指定接收地址为：<a class="modal-wallet" href="https://bscscan.com/address/0x420ef1f25563593af5fe3f9b9d3bc56a8bd8c104" target="_blank" rel="noopener noreferrer">0x420ef1f25563593af5fe3f9b9d3bc56a8bd8c104</a>转账将在发行后开始，具体安排及合约将在发行前公布。';
translations.en.modalPlan='The project’s 2% buy fee and 2% sell fee are designated for SAFU at:<a class="modal-wallet" href="https://bscscan.com/address/0x420ef1f25563593af5fe3f9b9d3bc56a8bd8c104" target="_blank" rel="noopener noreferrer">0x420ef1f25563593af5fe3f9b9d3bc56a8bd8c104</a>Transfers are planned after launch. The contract and transfer schedule will be published before launch.';
function language(lang){const data=translations[lang];document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.querySelectorAll('[data-i18n]').forEach(el=>{el.innerHTML=data[el.dataset.i18n]});for(const key of ['zh','en'])document.getElementById(key).setAttribute('aria-pressed',String(key===lang));document.querySelector('.close').setAttribute('aria-label',lang==='zh'?'关闭':'Close');document.querySelector('.languages').setAttribute('aria-label',lang==='zh'?'语言':'Language');document.querySelector('#scene').setAttribute('aria-label',lang==='zh'?'黄金圣殿中的金色护手互动 3D 场景':'Interactive golden gauntlets in the Golden Sanctum');try{localStorage.setItem('safuhands-language',lang)}catch{}}
let initial='zh';try{initial=localStorage.getItem('safuhands-language')==='en'?'en':'zh'}catch{}language(initial);document.querySelector('#zh').onclick=()=>language('zh');document.querySelector('#en').onclick=()=>language('en');
const dialog=document.querySelector('dialog');document.querySelector('#about').onclick=document.querySelector('#mission').onclick=()=>dialog.showModal();document.querySelector('.close').onclick=document.querySelector('#back').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}};document.querySelector('#retry').onclick=()=>location.reload();

document.querySelector('.copy-wallet').onclick=async()=>{const lang=document.documentElement.lang==='en'?'en':'zh';try{await navigator.clipboard.writeText('0x420ef1f25563593af5fe3f9b9d3bc56a8bd8c104');document.querySelector('#copy-status').textContent=translations[lang].walletCopied}catch{document.querySelector('#copy-status').textContent=translations[lang].walletCopyError}setTimeout(()=>document.querySelector('#copy-status').textContent='',3000)};
